"""問題集 第4章 イスラーム世界の形成と発展。問題・解説はすべて書き下ろし。
verify(): 形式（lv の数・空欄）、年代整序（年の辞書を sorted して答えと照合）、正誤の組合せ、
同時代の組合せ（年の差）、地図の記号と都市名の対応、論述の字数（len）を点検する。"""
import re

N = 4
NUM = "①②③④⑤⑥"
def B(s): return f'<div class="bun">{s}</div>'
def OPT(*xs): return "<br>".join(f"{NUM[i]} {x}" for i, x in enumerate(xs))
def AB(a, b): return f"<br>a　{a}<br>b　{b}"
def III(x, y, z): return f"<br>Ⅰ　{x}<br>Ⅱ　{y}<br>Ⅲ　{z}"
SEIJ = "<br>① a 正　b 正　② a 正　b 誤　③ a 誤　b 正　④ a 誤　b 誤"
ORD6 = ["ⅠⅡⅢ", "ⅠⅢⅡ", "ⅡⅠⅢ", "ⅡⅢⅠ", "ⅢⅠⅡ", "ⅢⅡⅠ"]
SEIRETSU = "<br>" + "　".join(f"{NUM[i]} {'→'.join(p)}" for i, p in enumerate(ORD6))

