ORDER = {6: {"Ⅰ": 732, "Ⅱ": 751, "Ⅲ": 642}}               # 年代整序
TF = {5: (True, True), 9: (False, True)}                      # 正誤判定 a, b
SYNC = {8: [(622, 720), (800, 800), (1055, 875), (1258, 960)]}  # 同時代の組合せ（各選択肢の2つの年）
MAPA = {7: ["e", "d", "a", "b"]}                              # 地図問題の答えの記号
ESSAY = {10: 100, 11: 100}                                    # 論述の字数制限
KEYW = {11: ["アラビア語", "ラテン語", "トレド"]}               # 指定語句


def verify():
    items = CH[N]["items"]
    lv = [it["lv"] for it in items]
    assert lv == sorted(lv) and lv.count("A") == 4 and 4 <= lv.count("B") <= 5 and lv.count("C") == 2, lv
    for i, it in enumerate(items, 1):
        for k in ("tag", "q", "a", "s"):
            assert isinstance(it[k], str) and it[k].strip(), (i, k)
            assert "$" not in it[k] and "@@" not in it[k], (i, k)
        assert "<b>ポイント</b>：" in it["s"], i
        assert it["q"].count("<div") == it["q"].count("</div>"), i
    for i, yrs in ORDER.items():
        seq = "".join(sorted(yrs, key=yrs.get))
        assert len(set(yrs.values())) == 3 and SEIRETSU in items[i - 1]["q"], i
        assert items[i - 1]["a"].startswith(NUM[ORD6.index(seq)]), (i, seq)
    TFM = {(True, True): "①", (True, False): "②", (False, True): "③", (False, False): "④"}
    for i, tf in TF.items():
        assert SEIJ in items[i - 1]["q"] and items[i - 1]["a"].startswith(TFM[tf]), i
    for i, pairs in SYNC.items():
        near = [k for k, (x, y) in enumerate(pairs) if abs(x - y) <= 30]
        assert len(near) == 1 and all(abs(x - y) >= 60 for k, (x, y) in enumerate(pairs) if k != near[0]), (i, pairs)
        assert items[i - 1]["a"].startswith(NUM[near[0]]), i
    for i, ans in MAPA.items():
        q, a = items[i - 1]["q"], items[i - 1]["a"]
        assert '<svg class="fig"' in q, i
        got = re.findall(r"([a-f])（(.+?)）", a)
        assert [l for l, _ in got] == ans and all(CITY[l] == nm for l, nm in got), (i, got)
        for l in CITY:
            assert f">{l}</text>" in q, (i, l)
    for i, lim in ESSAY.items():
        m = re.search(r"解答例：(.*?)（(\d+)字）", items[i - 1]["a"])
        body = m.group(1)
        assert len(body) == int(m.group(2)) and 0.8 * lim <= len(body) <= lim, (i, len(body), lim)
        assert f"{lim}字以内" in items[i - 1]["q"], i
        for w in KEYW.get(i, []):
            assert w in body, (i, w)
